DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.settle_appointment(uuid,jsonb,jsonb,boolean,text)'::regprocedure) INTO definition; definition:=replace(definition, 'coalesce(v,''null''::jsonb),issuer', 'CASE WHEN v IS NULL THEN ''null''::jsonb ELSE jsonb_build_object(''exempt'',v->''exempt'',''by'',v->''by'',''at'',v->''at'') END,issuer'); definition:=replace(definition,'ELSE t.btw_rate END','ELSE coalesce(t.btw_rate,0) END'); EXECUTE definition; END $$;
COMMENT ON COLUMN public.billing_settlements.fiscal_snapshot IS 'Financial decision/author/time only; never fiscal question answers or medical notes.';